	c.cache = make([]*CommitShort, 0)
	return c
}

func (p *CommitShortCache) Get() *CommitShort {
	var t *CommitShort
	p.mu.Lock()
	if len(p.cache) > 0 {
		t = p.cache[len(p.cache)-1]
		p.cache = p.cache[0:(len(p.cache) - 1)]
	}
	p.mu.Unlock()
	if t == nil {
		t = &CommitShort{}
	}
	return t
}
func (p *CommitShortCache) Put(t *CommitShort) {
	p.mu.Lock()
	p.cache = append(p.cache, t)
	p.mu.Unlock()
}
func (t *CommitShort) Marshal(wire io.Writer) {
	var b [16]byte
	var bs []byte
	bs = b[:16]
	tmp32 := t.LeaderId
	bs[0] = byte(tmp32)
	bs[1] = byte(tmp32 >> 8)
	bs[2] = byte(tmp32 >> 16)
	bs[3] = byte(tmp32 >> 24)
	tmp32 = t.Instance
	bs[4] = byte(tmp32)
	bs[5] = byte(tmp32 >> 8)
	bs[6] = byte(tmp32 >> 16)
	bs[7] = byte(tmp32 >> 24)
	tmp32 = t.Count
	bs[8] = byte(tmp32)
	bs[9] = byte(tmp32 >> 8)
	bs[10] = byte(tmp32 >> 16)
	bs[11] = byte(tmp32 >> 24)
	tmp32 = t.Ballot
	bs[12] = byte(tmp32)
	bs[13] = byte(tmp32 >> 8)
	bs[14] = byte(tmp32 >> 16)
	bs[15] = byte(tmp32 >> 24)
	wire.Write(bs)
}

func (t *CommitShort) Unmarshal(wire io.Reader) error {
	var b [16]byte
	var bs []byte
	bs = b[:16]
	if _, err := io.ReadAtLeast(wire, bs, 16); err != nil {
		return err
	}
	t.LeaderId = int32((uint32(bs[0]) | (uint32(bs[1]) << 8) | (uint32(bs[2]) << 16) | (uint32(bs[3]) << 24)))
	t.Instance = int32((uint32(bs[4]) | (uint32(bs[5]) << 8) | (uint32(bs[6]) << 16) | (uint32(bs[7]) << 24)))
	t.Count = int32((uint32(bs[8]) | (uint32(bs[9]) << 8) | (uint32(bs[10]) << 16) | (uint32(bs[11]) << 24)))
	t.Ballot = int32((uint32(bs[12]) | (uint32(bs[13]) << 8) | (uint32(bs[14]) << 16) | (uint32(bs[15]) << 24)))
	return nil
}","content_digest":"87b0469761c5ac61a8ce960b1b32024750ec71509d08c45448325c9342d03f49"},{"id":"replica/replica.go:350:577","file":"replica/replica.go","start_line":350,"end_line":577,"kind":"code_observation","content_digest":"ea28e2b94198a705e6dd9892a6154ce9b8cb424ec3dedeed8f8bd2488341e766","source_view_id":"source-view-3"},{"id":"replica/replica.go:137:349","file":"replica/replica.go","start_line":137,"end_line":349,"kind":"code_observation","content_digest":"ea28e2b94198a705e6dd9892a6154ce9b8cb424ec3dedeed8f8bd2488341e766","source_view_id":"source-view-3"},{"id":"replica/replica.go:1:136","file":"replica/replica.go","start_line":1,"end_line":136,"kind":"code_observation","content_digest":"ea28e2b94198a705e6dd9892a6154ce9b8cb424ec3dedeed8f8bd2488341e766","source_view_id":"source-view-3"}],"required_material_ids":["paxos/defs.go:1:558","paxos/paxos.go:161:397","paxos/paxos.go:24:160","paxos/paxos.go:398:538","replica/replica.go:137:349","replica/replica.go:1:136","replica/replica.go:350:577","rpc/rpc.go:1:48","state/state.go:1:80"],"explicit_material_ids":["replica/replica.go:1:136","state/state.go:1:80"],"omitted_material_ids":["README.md:1:80","client/client.go:1:80","replica/replica.go:1:80","dlog/dlog.go:1:67","config/config.go:1:80","client/buffer.go:1:80","run.go:23:103","master/master.go:187:300","replica/replica.go:81:136","paxos/paxos.go:539:666","paxos/paxos.go:667:736","client/client.go:142:256","master/master.go:1:186","replica/sender.go:1:206"],"omission_reason":"Outside this unit, its selected dependency closure and current semantic issues; full history remains archived","semantic_view":{"issue_reference_rule":"explanation_ref/source_ids_ref point to the exact unchanged fields of open_issues by issue ID; all alternatives and counterarguments remain on the judgment","judgments":[],"open_issues":[],"archive_access":"Request a focused review of a named issue/review to retrieve its archived reasoning; these are scoped opinions, not proof"},"unit":{"id":"u